from pathlib import Path

p=Path('admin.html')
s=p.read_text(encoding='utf-8')

old_css=""".blockedSchedule{\n  position:absolute;\n  top:8px;\n  height:82px;\n  z-index:3;\n  overflow:hidden;\n  padding:8px;\n  border:1px solid #dda8a1;\n  border-radius:10px;\n  background:#f4dfdc;\n  color:#8a4a42;\n  font-size:11px\n}\n"""
new_css=""".blockedSchedule{\n  position:absolute;\n  top:8px;\n  height:82px;\n  z-index:3;\n  overflow:hidden;\n  padding:8px 38px 8px 8px;\n  border:1px solid #dda8a1;\n  border-radius:10px;\n  background:#f4dfdc;\n  color:#8a4a42;\n  font-size:11px;\n  touch-action:pan-x\n}\n\n.blockedMoveHandle{\n  position:absolute;\n  right:3px;\n  top:50%;\n  transform:translateY(-50%);\n  z-index:40;\n  width:32px;\n  height:42px;\n  border:1px solid rgba(120,70,64,.35);\n  border-radius:9px;\n  background:rgba(255,255,255,.96);\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  color:#8a4a42;\n  font-size:17px;\n  font-weight:900;\n  line-height:1;\n  touch-action:none!important;\n  -webkit-user-select:none;\n  user-select:none;\n  -webkit-touch-callout:none;\n  box-shadow:0 1px 4px rgba(0,0,0,.10)\n}\n\n.blockedSchedule.directDragging{\n  z-index:120!important;\n  opacity:.96;\n  box-shadow:0 0 0 3px rgba(138,74,66,.22),0 8px 24px rgba(0,0,0,.20)\n}\n"""
if old_css not in s:
    raise SystemExit('blocked css anchor not found')
s=s.replace(old_css,new_css,1)

marker="""function renderTimeline(){\n"""
if marker not in s:
    raise SystemExit('renderTimeline marker not found')
helper="""function directBlockedTime(minutes){\n  const n=Math.max(DAY_START,Math.min(DAY_END,Number(minutes)||DAY_START));\n  return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}:00`;\n}\n\nfunction bindDirectBlockedMove(block,item,start,end){\n  const handle=block.querySelector('.blockedMoveHandle');\n  if(!handle||!item?.id)return;\n\n  handle.dataset.boundMove='1';\n  handle.addEventListener('click',event=>{\n    event.preventDefault();\n    event.stopPropagation();\n  });\n\n  handle.addEventListener('pointerdown',event=>{\n    if(event.pointerType==='mouse'&&event.button!==0)return;\n    const scroll=block.closest('.scheduleScroll,.timelineScroll');\n    if(!scroll)return;\n\n    const duration=end-start;\n    if(duration<=0)return;\n\n    event.preventDefault();\n    event.stopPropagation();\n\n    const pointerId=event.pointerId;\n    const startX=event.clientX;\n    const startScrollLeft=scroll.scrollLeft;\n    const originalLeft=parseFloat(block.style.left)||((start-DAY_START)*PX_PER_MINUTE);\n    let nextStart=start;\n    let finished=false;\n\n    block.classList.add('directDragging');\n    try{handle.setPointerCapture(pointerId)}catch{}\n\n    const move=ev=>{\n      if(ev.pointerId!==pointerId||finished)return;\n      ev.preventDefault();\n      ev.stopPropagation();\n      const moved=(ev.clientX-startX+scroll.scrollLeft-startScrollLeft)/PX_PER_MINUTE;\n      let candidate=Math.round((start+moved)/15)*15;\n      candidate=Math.max(DAY_START,Math.min(DAY_END-duration,candidate));\n      nextStart=candidate;\n      block.style.left=`${(candidate-DAY_START)*PX_PER_MINUTE}px`;\n      handle.textContent=directBlockedTime(candidate).slice(0,5);\n      handle.style.fontSize='10px';\n    };\n\n    const cleanup=()=>{\n      block.classList.remove('directDragging');\n      handle.textContent='↔';\n      handle.style.fontSize='17px';\n      handle.removeEventListener('pointermove',move);\n      handle.removeEventListener('pointerup',up);\n      handle.removeEventListener('pointercancel',cancel);\n      try{handle.releasePointerCapture(pointerId)}catch{}\n    };\n\n    const cancel=ev=>{\n      if(ev.pointerId!==pointerId||finished)return;\n      finished=true;\n      block.style.left=`${originalLeft}px`;\n      cleanup();\n    };\n\n    const up=async ev=>{\n      if(ev.pointerId!==pointerId||finished)return;\n      finished=true;\n      ev.preventDefault();\n      ev.stopPropagation();\n      cleanup();\n\n      if(nextStart===start){\n        block.style.left=`${originalLeft}px`;\n        return;\n      }\n\n      const oldLabel=directBlockedTime(start).slice(0,5);\n      const newLabel=directBlockedTime(nextStart).slice(0,5);\n      const newEnd=directBlockedTime(nextStart+duration).slice(0,5);\n      if(!confirm(`${oldLabel} → ${newLabel}（〜${newEnd}）に予定を移動しますか？`)){\n        block.style.left=`${originalLeft}px`;\n        return;\n      }\n\n      const {error}=await supabase.rpc('nakano_admin_move_blocked_time',{\n        p_blocked_id:String(item.id),\n        p_start_time:directBlockedTime(nextStart)\n      });\n\n      if(error){\n        console.error(error);\n        alert('その時間には移動できません。予約・別の予定を確認してください。');\n        block.style.left=`${originalLeft}px`;\n        return;\n      }\n\n      await loadDay();\n    };\n\n    handle.addEventListener('pointermove',move,{passive:false});\n    handle.addEventListener('pointerup',up,{passive:false});\n    handle.addEventListener('pointercancel',cancel,{passive:false});\n  },{passive:false});\n}\n\n"""
s=s.replace(marker,helper+marker,1)

old_html="""      block.innerHTML=`\n\n        <strong>\n          予約不可\n        </strong>\n\n        <br>\n\n        ${esc(item.memo||'')}\n\n      `;\n\n      block.style.cursor='grab';\n      block.title='タップで予定を変更・削除／左右ドラッグで時間変更';\n\n\n      lane.appendChild(\n        block\n      );\n"""
new_html="""      block.innerHTML=`\n\n        <strong>\n          予約不可\n        </strong>\n\n        <br>\n\n        ${esc(item.memo||'')}\n\n        <span\n          class=\"blockedMoveHandle\"\n          data-bound-move=\"1\"\n          role=\"button\"\n          aria-label=\"予定時間を左右に移動\"\n        >↔</span>\n\n      `;\n\n      block.style.cursor='pointer';\n      block.title='タップで予定を変更・削除／右端の↔で時間移動';\n\n      bindDirectBlockedMove(\n        block,\n        item,\n        start,\n        end\n      );\n\n      lane.appendChild(\n        block\n      );\n"""
if old_html not in s:
    raise SystemExit('blocked render anchor not found')
s=s.replace(old_html,new_html,1)

# build marker for visual verification
s=s.replace('<meta name="nakano-admin-build" content="2026-09-05-manual-booking-v2">','<meta name="nakano-admin-build" content="2026-09-05-direct-blocked-handle-v3">',1)

p.write_text(s,encoding='utf-8')
print('patched direct blocked move handle into admin')
